MAP
  NAME "webatlas"
  STATUS ON
  EXTENT 101 8 110 23.5
  UNITS DD
  IMAGECOLOR 255 255 255
  SHAPEPATH "/data"

  WEB
    METADATA
      "wms_title" "WebAtlas GIS Server"
      "wms_onlineresource" "http://localhost:8081/?"
      "wms_enable_request" "*"
      "wms_srs" "EPSG:4326 EPSG:3857"
      "wfs_enable_request" "*"
      "wfs_title" "WebAtlas WFS Server"
      "wfs_srs" "EPSG:4326 EPSG:3857"
    END
  END

  PROJECTION
    "init=epsg:4326"
  END

  # -----------------------------------------------------------
  # LAYER 1: Ranh giới Tỉnh (diaphantinh)
  # -----------------------------------------------------------
  LAYER
    NAME "diaphantinh"
    TYPE POLYGON
    CONNECTIONTYPE POSTGIS
    CONNECTION "host=postgis dbname=gis user=postgres password=postgres port=5432"
    DATA "geom FROM bien_gioi_tinh USING UNIQUE id USING SRID=4326"
    STATUS ON
    PROJECTION
      "init=epsg:4326"
    END
    METADATA
      "wms_title" "Ranh giới Tỉnh"
      "wms_name" "diaphantinh"
      "wms_srs" "EPSG:4326 EPSG:3857"
      "wfs_enable_request" "*"
      "gml_include_items" "all"
    END
    CLASS
      STYLE
        COLOR 240 240 240
        OUTLINECOLOR 100 100 100
        WIDTH 1.5
      END
    END
  END

  # -----------------------------------------------------------
  # LAYER 2: Ranh giới Xã/Phường (gadm41_vnm_3)
