      "wms_name" "gadm41_vnm_3"
      "wms_srs" "EPSG:4326 EPSG:3857"
      "wfs_enable_request" "*"
      "gml_include_items" "all"
    END
    CLASS
      STYLE
        COLOR 250 250 250
        OUTLINECOLOR 160 160 160
        WIDTH 0.8
      END
    END
  END

  # -----------------------------------------------------------
